<?php
class ElementorCallToAction extends \Elementor\Widget_Base {

	public function get_name() {
		return 'edgtf_call_to_action'; 
	}

	public function get_title() {
		return esc_html__( 'Edge Call To Action', 'goodwish' );
	}

	public function get_icon() {
		return 'goodwish-elementor-custom-icon goodwish-elementor-call-to-action';
	}

	public function get_categories() {
		return [ 'edge' ];
	}

	protected function _register_controls() {

		$this->start_controls_section(
			'general',
			[
				'label' => esc_html__( 'General', 'goodwish' ),
				'tab'   => \Elementor\Controls_Manager::TAB_CONTENT,
			]
		);
		$this->add_control(
			'full_width',
			[
				'label'     => esc_html__( 'Full Width', 'goodwish' ),
				'type'      => \Elementor\Controls_Manager::SELECT,
				'options' => array(
					'yes' => esc_html__( 'Yes', 'goodwish'),
					'no' => esc_html__( 'No', 'goodwish')
				),
				'default' => 'yes'
			]
		);

		$this->add_control(
			'content_in_grid',
			[
				'label'     => esc_html__( 'Content in grid', 'goodwish' ),
				'type'      => \Elementor\Controls_Manager::SELECT,
				'options' => array(
					'yes' => esc_html__( 'Yes', 'goodwish'),
					'no' => esc_html__( 'No', 'goodwish')
				),
				'default' => 'yes',
				'condition' => [
					'full_width' => array( 'yes' )
				]
			]
		);

		$this->add_control(
			'grid_size',
			[
				'label'     => esc_html__( 'Grid size', 'goodwish' ),
				'type'      => \Elementor\Controls_Manager::SELECT,
				'options' => array(
					'75' => esc_html__( '75/25', 'goodwish'),
					'50' => esc_html__( '50/50', 'goodwish'),
					'66' => esc_html__( '66/33', 'goodwish')
				),
				'default' => '75',
				'condition' => [
					'content_in_grid' => array( 'yes' )
				]
			]
		);

		$this->add_control(
			'type',
			[
				'label'     => esc_html__( 'Type', 'goodwish' ),
				'type'      => \Elementor\Controls_Manager::SELECT,
				'options' => array(
					'normal' => esc_html__( 'Normal', 'goodwish'),
					'with-icon' => esc_html__( 'With Icon', 'goodwish')
				),
				'default' => 'normal'
			]
		);

		goodwish_edge_icon_collections()->getElementorParamsArray( $this, array('type' => array('with-icon')), '' );
		$this->add_control(
			'show_button',
			[
				'label'     => esc_html__( 'Show Button', 'goodwish' ),
