				'label'     => esc_html__( 'Button Position', 'goodwish' ),
				'type'      => \Elementor\Controls_Manager::SELECT,
				'options' => array(
					'' => esc_html__( 'Default/right', 'goodwish'),
					'center' => esc_html__( 'Center', 'goodwish'),
					'left' => esc_html__( 'Left', 'goodwish')
				),
				'default' => 'right',
				'condition' => [
					'show_button' => array( 'yes' )
				]
			]
